import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"常见问题","description":"关于 CertHub 的免费范围、证书来源、泛域名、凭据显示、多用户、接口与数据备份的常见问题。","frontmatter":{"title":"常见问题","description":"关于 CertHub 的免费范围、证书来源、泛域名、凭据显示、多用户、接口与数据备份的常见问题。"},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),h={name:"faq.md"};function i(s,a,l,d,n,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="关于产品" tabindex="-1">关于产品 <a class="header-anchor" href="#关于产品" aria-label="Permalink to &quot;关于产品&quot;">​</a></h2><h3 id="certhub-真的完全免费吗" tabindex="-1">CertHub 真的完全免费吗？ <a class="header-anchor" href="#certhub-真的完全免费吗" aria-label="Permalink to &quot;CertHub 真的完全免费吗？&quot;">​</a></h3><p>是。没有付费、授权、套餐、钱包、邀请返佣等任何商业模块，也不限制流水线数量、站点监控数量、通知渠道数量。可以自由私有化部署。</p><h3 id="开源协议是什么" tabindex="-1">开源协议是什么？ <a class="header-anchor" href="#开源协议是什么" aria-label="Permalink to &quot;开源协议是什么？&quot;">​</a></h3><p>GPL-3.0。可以自建、可以改、可以内部使用；对外分发衍生作品时需要同样开源。</p><h3 id="需要什么环境" tabindex="-1">需要什么环境？ <a class="header-anchor" href="#需要什么环境" aria-label="Permalink to &quot;需要什么环境？&quot;">​</a></h3><p>Python 3.11+，一个端口（默认 8000）。构建前端时额外需要 Node.js 18+，但服务器可以直接用构建好的产物。</p><h3 id="支持多用户吗" tabindex="-1">支持多用户吗？ <a class="header-anchor" href="#支持多用户吗" aria-label="Permalink to &quot;支持多用户吗？&quot;">​</a></h3><p>支持。角色两级（管理员 / 普通用户），数据按用户隔离，另有「用户组」可以按功能键授权（例如只给流水线权限、不给凭据权限）。自助注册默认关闭，需要时在系统设置里打开。</p><h2 id="关于证书" tabindex="-1">关于证书 <a class="header-anchor" href="#关于证书" aria-label="Permalink to &quot;关于证书&quot;">​</a></h2><h3 id="支持哪些证书颁发机构" tabindex="-1">支持哪些证书颁发机构？ <a class="header-anchor" href="#支持哪些证书颁发机构" aria-label="Permalink to &quot;支持哪些证书颁发机构？&quot;">​</a></h3><p>通过 ACME 对接 Let&#39;s Encrypt、Google Trust Services、ZeroSSL、FreeSSL / LiteSSL、Buypass 与自定义 CA；另外支持阿里云、腾讯云、火山引擎的免费证书，TrustAsia 商业证书，本地自签与自有证书导入。完整清单见 <a href="/ecosystem.html">生态集成</a>。</p><h3 id="泛域名怎么配" tabindex="-1">泛域名怎么配？ <a class="header-anchor" href="#泛域名怎么配" aria-label="Permalink to &quot;泛域名怎么配？&quot;">​</a></h3><p>用 <strong>DNS-01</strong> 验证（HTTP-01 不支持泛域名），域名写 <code>*.example.com</code>，<strong>同时把 <code>example.com</code> 也加进域名列表</strong>，否则主域不在证书覆盖范围内。</p><h3 id="会不会重复申请触发限流" tabindex="-1">会不会重复申请触发限流？ <a class="header-anchor" href="#会不会重复申请触发限流" aria-label="Permalink to &quot;会不会重复申请触发限流？&quot;">​</a></h3><p>不会。证书任务有「提前续期天数」（默认 20 天），没到续期时间会自动跳过签发，复用证书库里的证书。定时任务设成每天跑是安全的。</p><h3 id="云厂商免费证书有什么限制" tabindex="-1">云厂商免费证书有什么限制？ <a class="header-anchor" href="#云厂商免费证书有什么限制" aria-label="Permalink to &quot;云厂商免费证书有什么限制？&quot;">​</a></h3><p>阿里云 / 腾讯云是 3 个月的<strong>单域名 DV</strong>，火山引擎以控制台为准，都受账号免费额度限制，额度用尽会直接返回业务错误。泛域名请走 ACME。</p><h3 id="证书能导出成什么格式" tabindex="-1">证书能导出成什么格式？ <a class="header-anchor" href="#证书能导出成什么格式" aria-label="Permalink to &quot;证书能导出成什么格式？&quot;">​</a></h3><p>PEM、DER、PFX（PKCS#12）、P7B、JKS、Nginx 格式，可只导证书或只导私钥。JKS 需要服务器装了 JDK（<code>keytool</code>），没装时建议改用 PFX。</p><h2 id="关于部署" tabindex="-1">关于部署 <a class="header-anchor" href="#关于部署" aria-label="Permalink to &quot;关于部署&quot;">​</a></h2><h3 id="能部署到哪些地方" tabindex="-1">能部署到哪些地方？ <a class="header-anchor" href="#能部署到哪些地方" aria-label="Permalink to &quot;能部署到哪些地方？&quot;">​</a></h3><p>75 个内置插件：主机与中间件、面板、集群、云 CDN、对象存储，以及 Webhook / 脚本 / 命令等通用任务。完整清单见 <a href="/docs/deploy.html">部署目标</a>。</p><h3 id="内网机器能部署吗" tabindex="-1">内网机器能部署吗？ <a class="header-anchor" href="#内网机器能部署吗" aria-label="Permalink to &quot;内网机器能部署吗？&quot;">​</a></h3><p>能。用主机 SSH 授权，从平台所在的机器连过去即可。注意内网地址不要走 HTTP 代理（插件内部已经处理了这点）。</p><h3 id="我的平台不在清单里怎么办" tabindex="-1">我的平台不在清单里怎么办？ <a class="header-anchor" href="#我的平台不在清单里怎么办" aria-label="Permalink to &quot;我的平台不在清单里怎么办？&quot;">​</a></h3><p>三条通用路径：主机 SSH + 自定义重载命令、Webhook 推给自有系统、在目标主机执行脚本。也可以按 <a href="/docs/plugin-dev.html">新增插件</a> 自己加一个。</p><h2 id="关于安全" tabindex="-1">关于安全 <a class="header-anchor" href="#关于安全" aria-label="Permalink to &quot;关于安全&quot;">​</a></h2><h3 id="为什么接口里能看到明文密钥" tabindex="-1">为什么接口里能看到明文密钥？ <a class="header-anchor" href="#为什么接口里能看到明文密钥" aria-label="Permalink to &quot;为什么接口里能看到明文密钥？&quot;">​</a></h3><p>这是刻意的设计：打码会让用户以为「没保存」，排障时也无法确认到底填了什么。所以数据库里 AES-GCM 加密存储，接口按设计明文返回，界面上的密码框默认星号、点「小眼睛」才显示明文。</p><p>代价是：<strong>数据库文件与备份文件必须当机密文件对待</strong>。</p><h3 id="编辑时把密码框清空会丢密钥吗" tabindex="-1">编辑时把密码框清空会丢密钥吗？ <a class="header-anchor" href="#编辑时把密码框清空会丢密钥吗" aria-label="Permalink to &quot;编辑时把密码框清空会丢密钥吗？&quot;">​</a></h3><p>不会。留空表示「这一项没改」，后端会还原旧值，绝不会把密钥写成空串。</p><h3 id="有没有两步验证和审计日志" tabindex="-1">有没有两步验证和审计日志？ <a class="header-anchor" href="#有没有两步验证和审计日志" aria-label="Permalink to &quot;有没有两步验证和审计日志？&quot;">​</a></h3><p>有。支持 TOTP 两步验证（扫码绑定）、登录失败锁定、图形验证码、登录提醒，以及记录关键操作的审计日志。</p><h2 id="关于数据" tabindex="-1">关于数据 <a class="header-anchor" href="#关于数据" aria-label="Permalink to &quot;关于数据&quot;">​</a></h2><h3 id="数据存在哪里" tabindex="-1">数据存在哪里？ <a class="header-anchor" href="#数据存在哪里" aria-label="Permalink to &quot;数据存在哪里？&quot;">​</a></h3><p>默认 <code>backend/data</code>：<code>certd.db</code>（数据库）、<code>certs/</code>（证书文件）、<code>secret.key</code>（加密密钥）。可以用 <code>CERTD_DATA_DIR</code> 改。</p><h3 id="怎么备份" tabindex="-1">怎么备份？ <a class="header-anchor" href="#怎么备份" aria-label="Permalink to &quot;怎么备份？&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/backup.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/backup/certhub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span></span></code></pre></div><p>包含数据库、证书文件与 <code>secret.key</code>。恢复用 <code>--restore</code>，会先把当前库另存一份。详见 <a href="/docs/ops.html">备份与升级</a>。</p><h3 id="升级会丢数据吗" tabindex="-1">升级会丢数据吗？ <a class="header-anchor" href="#升级会丢数据吗" aria-label="Permalink to &quot;升级会丢数据吗？&quot;">​</a></h3><p>不会。数据目录与代码分离，升级只替换代码。但升级前请先备份，尤其是要固定 <code>CERTD_SECRET_KEY</code> / 保留 <code>secret.key</code>。</p><h2 id="关于接口" tabindex="-1">关于接口 <a class="header-anchor" href="#关于接口" aria-label="Permalink to &quot;关于接口&quot;">​</a></h2><h3 id="有-api-吗" tabindex="-1">有 API 吗？ <a class="header-anchor" href="#有-api-吗" aria-label="Permalink to &quot;有 API 吗？&quot;">​</a></h3><p>有。登录态接口用 <code>Authorization</code> token；给脚本 / CI 用的开放接口用 API 密钥（<code>x-api-key</code> + <code>x-api-secret</code>），可以列流水线、触发运行、读证书。见 <a href="/docs/dev.html">架构与目录</a>。</p><h3 id="能对接我自己的监控系统吗" tabindex="-1">能对接我自己的监控系统吗？ <a class="header-anchor" href="#能对接我自己的监控系统吗" aria-label="Permalink to &quot;能对接我自己的监控系统吗？&quot;">​</a></h3><p><code>GET /api/health</code> 返回数据库、磁盘、调度器状态，异常时返回 503，可以直接给 Uptime Kuma / 云监控用。</p><hr><p>没找到答案？看 <a href="/docs/troubleshoot.html">故障排查</a>，或在 GitHub 仓库提 issue（带上执行历史里的完整日志）。</p>',51)])])}const b=e(h,[["render",i]]);export{u as __pageData,b as default};
